// Input: Telegram message that starts with /checkin
const message = $input.all()[0].json.message;
const userId = message.from.id;
const text = message.text; // e.g., "/checkin My Awesome Pop-Up"

let shopName = '';
const commandParts = text.split(' ');
if (commandParts.length > 1) {
  shopName = commandParts.slice(1).join(' '); // Get everything after "/checkin "
}

if (shopName) {
  // Initialize staticData if it doesn't exist
  if (workflow.staticData === undefined) {
    workflow.staticData = {};
  }
  // Store shop name associated with the user ID
  workflow.staticData[userId] = { 
    shopName: shopName, 
    timestamp: Date.now() // Store timestamp for potential expiry
  };

  // Return data that can be used to send a confirmation message
  return { 
    chatId: message.chat.id,
    text: `✅ Shop name "${shopName}" received. Please send your location now.` 
  };
} else {
  // Invalid command format
  return {
    chatId: message.chat.id,
    text: "⚠️ Please provide a shop name after /checkin. Example: /checkin Main Street Pop-Up"
  };
}

// Input: Telegram message that contains a location
const message = $input.all()[0].json.message;
const userId = message.from.id;

// Ensure staticData exists and the user has an entry
if (workflow.staticData && workflow.staticData[userId] && workflow.staticData[userId].shopName) {
  const userData = workflow.staticData[userId];
  const shopName = userData.shopName;

  const maxAgeMs = 10 * 60 * 1000; // 10 minutes
  if (Date.now() - userData.timestamp > maxAgeMs) {
    delete workflow.staticData[userId];
    return {
      error: true,
      chatId: message.chat.id,
      text: "⚠️ Your shop name session has expired. Please use /checkin <Shop Name> again before sending location."
    };
  }

  delete workflow.staticData[userId]; // Clear after retrieval

  if (message.location) {
    return {
      shopName: shopName,
      timestamp: new Date(message.date * 1000).toISOString(),
      salesperson: message.from.username || message.from.first_name,
      userId: userId,
      chatId: message.chat.id,
      lat: message.location.latitude,
      lng: message.location.longitude,
      accuracy: message.location.horizontal_accuracy,
      error: false
    };
  }
}

// If no shop name or location not present as expected by this path.
return {
  error: true,
  chatId: message.chat.id,
  text: "⚠️ Please use the /checkin <Shop Name> command first, and then send your location."
};

